  completed_at TIMESTAMPTZ,
  rejection_reason STRING(500),
  export_file_ref STRING(500),
  export_expires_at TIMESTAMPTZ,
  CONSTRAINT pk_data_subject_request PRIMARY KEY (id),
  CONSTRAINT ck_data_subject_request_due_after_receipt CHECK (due_at >= received_at),
  CONSTRAINT ck_data_subject_request_completed_after_receipt CHECK (completed_at IS NULL OR completed_at >= received_at),
  CONSTRAINT fk_data_subject_request_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_data_subject_request_dsr_type_id FOREIGN KEY (dsr_type_id) REFERENCES dsr_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_data_subject_request_dsr_status_id FOREIGN KEY (dsr_status_id) REFERENCES dsr_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_data_subject_request_request_channel_id FOREIGN KEY (request_channel_id) REFERENCES request_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_data_subject_request_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_data_subject_request_assigned_to_app_user_id FOREIGN KEY (assigned_to_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_data_subject_request_dsr_status_id_due_at (dsr_status_id, due_at) WHERE completed_at IS NULL AND deleted_at IS NULL,
  INDEX idx_data_subject_request_app_user_id_received_at (app_user_id, received_at DESC),
  INDEX idx_data_subject_request_assigned_to_app_user_id_due_at (assigned_to_app_user_id, due_at) WHERE completed_at IS NULL AND assigned_to_app_user_id IS NOT NULL,
  INDEX idx_data_subject_request_country_id (country_id) WHERE country_id IS NOT NULL
);
