CREATE TABLE IF NOT EXISTS duplicate_candidate_match (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  primary_app_user_id UUID NOT NULL,
  duplicate_app_user_id UUID NOT NULL,
  duplicate_match_rule_id UUID NOT NULL,
  match_confidence DECIMAL(5,2) NOT NULL DEFAULT 0,
  duplicate_match_status_id UUID NOT NULL,
  evidence JSONB,
  reviewed_at TIMESTAMPTZ,
  reviewed_by_app_user_id UUID,
  CONSTRAINT pk_duplicate_candidate_match PRIMARY KEY (id),
  CONSTRAINT uq_duplicate_candidate_match_pair_rule UNIQUE (primary_app_user_id, duplicate_app_user_id, duplicate_match_rule_id),
  CONSTRAINT ck_duplicate_candidate_match_canonical_order CHECK (primary_app_user_id < duplicate_app_user_id),
  CONSTRAINT ck_duplicate_candidate_match_confidence_range CHECK (match_confidence BETWEEN 0 AND 100),
  CONSTRAINT ck_duplicate_candidate_match_review_pair CHECK ((reviewed_at IS NULL) = (reviewed_by_app_user_id IS NULL)),
  CONSTRAINT fk_duplicate_candidate_match_primary_app_user_id FOREIGN KEY (primary_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_duplicate_candidate_match_duplicate_app_user_id FOREIGN KEY (duplicate_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_duplicate_candidate_match_duplicate_match_rule_id FOREIGN KEY (duplicate_match_rule_id) REFERENCES duplicate_match_rule (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_duplicate_candidate_match_duplicate_match_status_id FOREIGN KEY (duplicate_match_status_id) REFERENCES duplicate_match_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_duplicate_candidate_match_reviewed_by_app_user_id FOREIGN KEY (reviewed_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_duplicate_candidate_match_duplicate_app_user_id (duplicate_app_user_id),
  INDEX idx_duplicate_candidate_match_duplicate_match_status_id_match_confidence (duplicate_match_status_id, match_confidence DESC) WHERE reviewed_at IS NULL,
  INDEX idx_duplicate_candidate_match_reviewed_by_app_user_id (reviewed_by_app_user_id) WHERE reviewed_by_app_user_id IS NOT NULL
);
