  CONSTRAINT uq_legacy_record_map_legacy_source_system_id_legacy_entity_kind_id_platform_record_ref UNIQUE (legacy_source_system_id, legacy_entity_kind_id, platform_record_ref),
  CONSTRAINT ck_legacy_record_map_tombstone CHECK (is_tombstoned = (tombstoned_at IS NOT NULL)),
