  INDEX idx_legacy_sync_conflict_resolved_by_app_user_id (resolved_by_app_user_id) WHERE resolved_by_app_user_id IS NOT NULL,
  INDEX idx_legacy_sync_conflict_sync_conflict_policy_id (sync_conflict_policy_id)
) WITH (ttl_expiration_expression = '(detected_at + INTERVAL ''24 months'')', ttl_job_cron = '@daily');
