  closed_at TIMESTAMPTZ,
  CONSTRAINT pk_moderation_case PRIMARY KEY (id),
  CONSTRAINT ck_moderation_case_priority_range CHECK (priority BETWEEN 1 AND 5),
  CONSTRAINT ck_moderation_case_range CHECK (closed_at IS NULL OR closed_at >= opened_at),
  CONSTRAINT fk_moderation_case_moderation_target_type_id FOREIGN KEY (moderation_target_type_id) REFERENCES moderation_target_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_moderation_case_target_app_user_id FOREIGN KEY (target_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_moderation_case_reporter_app_user_id FOREIGN KEY (reporter_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_moderation_case_moderation_reason_id FOREIGN KEY (moderation_reason_id) REFERENCES moderation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_moderation_case_moderation_case_status_id FOREIGN KEY (moderation_case_status_id) REFERENCES moderation_case_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_moderation_case_assigned_to_app_user_id FOREIGN KEY (assigned_to_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
