  INDEX idx_moderation_case_assigned_to_app_user_id (assigned_to_app_user_id) WHERE assigned_to_app_user_id IS NOT NULL AND closed_at IS NULL,
  INDEX idx_moderation_case_moderation_target_type_id_target_ref (moderation_target_type_id, target_ref)
);
