CREATE TABLE IF NOT EXISTS purge_job_run (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  data_retention_policy_id UUID NOT NULL,
  job_run_status_id UUID NOT NULL,
  cutoff_at TIMESTAMPTZ NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at TIMESTAMPTZ,
  rows_scanned INT8 NOT NULL DEFAULT 0,
  rows_purged INT8 NOT NULL DEFAULT 0,
  rows_held INT8 NOT NULL DEFAULT 0,
  is_dry_run BOOL NOT NULL DEFAULT false,
  error_summary STRING(1000),
  CONSTRAINT pk_purge_job_run PRIMARY KEY (id),
  CONSTRAINT ck_purge_job_run_finished_after_start CHECK (finished_at IS NULL OR finished_at >= started_at),
  CONSTRAINT ck_purge_job_run_counts CHECK (rows_scanned >= 0 AND rows_purged >= 0 AND rows_held >= 0 AND rows_purged + rows_held <= rows_scanned),
  CONSTRAINT fk_purge_job_run_data_retention_policy_id FOREIGN KEY (data_retention_policy_id) REFERENCES data_retention_policy (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_purge_job_run_job_run_status_id FOREIGN KEY (job_run_status_id) REFERENCES job_run_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_purge_job_run_data_retention_policy_id_started_at (data_retention_policy_id, started_at DESC)
);
