  updated_by UUID NOT NULL,
  blocker_app_user_id UUID NOT NULL,
  blocked_app_user_id UUID NOT NULL,
  blocker_actor_type_id UUID NOT NULL,
  blocked_actor_type_id UUID NOT NULL,
