  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  CONSTRAINT pk_user_block PRIMARY KEY (id),
  CONSTRAINT ck_user_block_not_self CHECK (blocker_app_user_id <> blocked_app_user_id),
  CONSTRAINT ck_user_block_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT fk_user_block_blocker_app_user_id FOREIGN KEY (blocker_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_block_blocked_app_user_id FOREIGN KEY (blocked_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
