  CONSTRAINT fk_user_consent_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_consent_consent_type_id FOREIGN KEY (consent_type_id) REFERENCES consent_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_consent_consent_document_id FOREIGN KEY (consent_document_id) REFERENCES consent_document (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
