  CONSTRAINT fk_user_consent_consent_source_id FOREIGN KEY (consent_source_id) REFERENCES consent_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_consent_recorded_by_app_user_id FOREIGN KEY (recorded_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_consent_consent_document_type FOREIGN KEY (consent_document_id, consent_type_id) REFERENCES consent_document (id, consent_type_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_user_consent_app_user_id_consent_type_id_occurred_at (app_user_id, consent_type_id, occurred_at DESC) STORING (consent_action_id, consent_document_id),
  INDEX idx_user_consent_consent_document_id (consent_document_id),
  INDEX idx_user_consent_occurred_at (occurred_at) USING HASH WITH (bucket_count = 16),
