CREATE TABLE IF NOT EXISTS user_credential (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  app_user_id UUID NOT NULL,
  password_hash STRING(255) NOT NULL,
  hash_algorithm_id UUID NOT NULL,
  argon2_memory_kib INT4,
  argon2_iterations INT2,
  argon2_parallelism INT2,
  pepper_version INT2,
  is_active BOOL NOT NULL DEFAULT true,
  credential_change_reason_id UUID NOT NULL,
  password_set_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  must_change BOOL NOT NULL DEFAULT false,
  breach_checked_at TIMESTAMPTZ,
  breach_detected_at TIMESTAMPTZ,
  deactivated_at TIMESTAMPTZ,
  CONSTRAINT pk_user_credential PRIMARY KEY (id),
  CONSTRAINT ck_user_credential_active_state CHECK (is_active = (deactivated_at IS NULL)),
  CONSTRAINT ck_user_credential_argon_params CHECK (hash_algorithm_id IS NOT NULL AND (argon2_memory_kib IS NULL OR argon2_memory_kib >= 19456)),
  CONSTRAINT ck_user_credential_expiry_after_set CHECK (expires_at IS NULL OR expires_at > password_set_at),
  CONSTRAINT fk_user_credential_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_credential_hash_algorithm_id FOREIGN KEY (hash_algorithm_id) REFERENCES hash_algorithm (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_credential_credential_change_reason_id FOREIGN KEY (credential_change_reason_id) REFERENCES credential_change_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_user_credential_app_user_id_active (app_user_id) WHERE is_active,
  INDEX idx_user_credential_app_user_id_password_set_at (app_user_id, password_set_at DESC),
  INDEX idx_user_credential_breach_detected_at (breach_detected_at) WHERE breach_detected_at IS NOT NULL AND is_active
);
