  released_at TIMESTAMPTZ,
  CONSTRAINT pk_legal_hold PRIMARY KEY (id),
  CONSTRAINT uq_legal_hold_hold_reference UNIQUE (hold_reference),
  CONSTRAINT ck_legal_hold_exactly_one_scope CHECK ((CASE WHEN app_user_id IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN organisation_id IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN entity_table_name IS NOT NULL THEN 1 ELSE 0 END) = 1),
  CONSTRAINT ck_legal_hold_released_after_placed CHECK (released_at IS NULL OR released_at >= placed_at),
  CONSTRAINT fk_legal_hold_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
