  INDEX idx_legal_hold_app_user_id (app_user_id) WHERE released_at IS NULL AND app_user_id IS NOT NULL,
  INDEX idx_legal_hold_organisation_id (organisation_id) WHERE released_at IS NULL AND organisation_id IS NOT NULL,
  INDEX idx_legal_hold_entity_table_name (entity_table_name) WHERE released_at IS NULL AND entity_table_name IS NOT NULL
);
