  approver_app_user_id UUID,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  access_starts_at TIMESTAMPTZ,
  access_ends_at TIMESTAMPTZ,
  granted_app_user_role_id UUID,
  revoked_at TIMESTAMPTZ,
  reviewed_at TIMESTAMPTZ,
  reviewed_by_app_user_id UUID,
  CONSTRAINT pk_privileged_access_request PRIMARY KEY (id),
  CONSTRAINT ck_privileged_access_request_different_people CHECK (approver_app_user_id IS NULL OR approver_app_user_id <> requesting_app_user_id),
  CONSTRAINT ck_privileged_access_request_window CHECK (access_starts_at IS NULL OR (access_ends_at > access_starts_at AND access_ends_at <= access_starts_at + INTERVAL '4 hours')),
  CONSTRAINT ck_privileged_access_request_window_pair CHECK ((access_starts_at IS NULL) = (access_ends_at IS NULL)),
  CONSTRAINT fk_privileged_access_request_requesting_app_user_id FOREIGN KEY (requesting_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_privileged_access_request_requested_app_role_id FOREIGN KEY (requested_app_role_id) REFERENCES app_role (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_privileged_access_request_approval_status_id FOREIGN KEY (approval_status_id) REFERENCES approval_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_privileged_access_request_approver_app_user_id FOREIGN KEY (approver_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_privileged_access_request_granted_app_user_role_id FOREIGN KEY (granted_app_user_role_id) REFERENCES app_user_role (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_privileged_access_request_reviewed_by_app_user_id FOREIGN KEY (reviewed_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_privileged_access_request_requesting_app_user_id_requested_at (requesting_app_user_id, requested_at DESC),
  INDEX idx_privileged_access_request_requested_app_role_id (requested_app_role_id),
  INDEX idx_privileged_access_request_approver_app_user_id (approver_app_user_id) WHERE approver_app_user_id IS NOT NULL,
  INDEX idx_privileged_access_request_granted_app_user_role_id (granted_app_user_role_id) WHERE granted_app_user_role_id IS NOT NULL,
  INDEX idx_privileged_access_request_reviewed_by_app_user_id (reviewed_by_app_user_id) WHERE reviewed_by_app_user_id IS NOT NULL,
  INDEX idx_privileged_access_request_approval_status_id_access_ends_at (approval_status_id, access_ends_at) WHERE revoked_at IS NULL AND access_ends_at IS NOT NULL
);
