  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  CONSTRAINT pk_trusted_ip PRIMARY KEY (id),
  CONSTRAINT ck_trusted_ip_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT fk_trusted_ip_ip_rule_kind_id FOREIGN KEY (ip_rule_kind_id) REFERENCES ip_rule_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_trusted_ip_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_trusted_ip_app_role_id FOREIGN KEY (app_role_id) REFERENCES app_role (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_trusted_ip_organisation_id_app_role_id (organisation_id, app_role_id) WHERE effective_to IS NULL,
  INDEX idx_trusted_ip_app_role_id (app_role_id) WHERE app_role_id IS NOT NULL
);
-- @@
CREATE TABLE IF NOT EXISTS user_merge_request (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  surviving_app_user_id UUID NOT NULL,
  merged_app_user_id UUID NOT NULL,
  duplicate_candidate_match_id UUID,
  admin_action_approval_id UUID,
  approval_status_id UUID NOT NULL,
  merge_plan JSONB,
  executed_at TIMESTAMPTZ,
  undo_until_at TIMESTAMPTZ,
  CONSTRAINT pk_user_merge_request PRIMARY KEY (id),
  CONSTRAINT ck_user_merge_request_not_self CHECK (surviving_app_user_id <> merged_app_user_id),
  CONSTRAINT ck_user_merge_request_undo_after_exec CHECK ((executed_at IS NULL) = (undo_until_at IS NULL)),
  CONSTRAINT fk_user_merge_request_surviving_app_user_id FOREIGN KEY (surviving_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_merge_request_merged_app_user_id FOREIGN KEY (merged_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_merge_request_duplicate_candidate_match_id FOREIGN KEY (duplicate_candidate_match_id) REFERENCES duplicate_candidate_match (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_user_merge_request_admin_action_approval_id FOREIGN KEY (admin_action_approval_id) REFERENCES admin_action_approval (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_user_merge_request_approval_status_id FOREIGN KEY (approval_status_id) REFERENCES approval_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_user_merge_request_merged_app_user_id (merged_app_user_id) WHERE executed_at IS NOT NULL,
  INDEX idx_user_merge_request_surviving_app_user_id_created_at (surviving_app_user_id, created_at DESC),
  INDEX idx_user_merge_request_duplicate_candidate_match_id (duplicate_candidate_match_id) WHERE duplicate_candidate_match_id IS NOT NULL,
  INDEX idx_user_merge_request_admin_action_approval_id (admin_action_approval_id) WHERE admin_action_approval_id IS NOT NULL,
  INDEX idx_user_merge_request_approval_status_id (approval_status_id)
);
-- @@
CREATE TABLE IF NOT EXISTS impersonation_session (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  support_app_user_id UUID NOT NULL,
  impersonated_app_user_id UUID NOT NULL,
  impersonation_reason_id UUID NOT NULL,
  support_ticket_id UUID,
  admin_action_approval_id UUID,
  is_read_only BOOL NOT NULL DEFAULT true,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL,
  action_count INT4 NOT NULL DEFAULT 0,
  CONSTRAINT pk_impersonation_session PRIMARY KEY (id),
  CONSTRAINT ck_impersonation_session_not_self CHECK (support_app_user_id <> impersonated_app_user_id),
  CONSTRAINT ck_impersonation_session_range CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT ck_impersonation_session_expiry CHECK (expires_at > started_at),
  CONSTRAINT ck_impersonation_session_write_needs_approval CHECK (is_read_only OR admin_action_approval_id IS NOT NULL),
  CONSTRAINT fk_impersonation_session_support_app_user_id FOREIGN KEY (support_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_impersonation_session_impersonated_app_user_id FOREIGN KEY (impersonated_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_impersonation_session_impersonation_reason_id FOREIGN KEY (impersonation_reason_id) REFERENCES impersonation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_impersonation_session_admin_action_approval_id FOREIGN KEY (admin_action_approval_id) REFERENCES admin_action_approval (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_impersonation_session_support_app_user_id_open (support_app_user_id) WHERE ended_at IS NULL,
  INDEX idx_impersonation_session_impersonated_app_user_id_started_at (impersonated_app_user_id, started_at DESC),
  INDEX idx_impersonation_session_support_ticket_id (support_ticket_id) WHERE support_ticket_id IS NOT NULL,
  INDEX idx_impersonation_session_admin_action_approval_id (admin_action_approval_id) WHERE admin_action_approval_id IS NOT NULL
);
-- @@
CREATE TABLE IF NOT EXISTS organisation_block (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  organisation_id UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  block_direction_id UUID NOT NULL,
  block_reason_id UUID NOT NULL,
  initiated_by_app_user_id UUID,
  note STRING(500),
  effective_from TIMESTAMPTZ NOT NULL DEFAULT now(),
  effective_to TIMESTAMPTZ,
  CONSTRAINT pk_organisation_block PRIMARY KEY (id),
  CONSTRAINT ck_organisation_block_range CHECK (effective_to IS NULL OR effective_to >= effective_from),
  CONSTRAINT fk_organisation_block_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_block_block_direction_id FOREIGN KEY (block_direction_id) REFERENCES block_direction (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_block_block_reason_id FOREIGN KEY (block_reason_id) REFERENCES block_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_organisation_block_initiated_by_app_user_id FOREIGN KEY (initiated_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_organisation_block_organisation_id_candidate_profile_id_block_direction_id_open (organisation_id, candidate_profile_id, block_direction_id) WHERE effective_to IS NULL,
  INDEX idx_organisation_block_candidate_profile_id_organisation_id_open (candidate_profile_id, organisation_id) WHERE effective_to IS NULL,
  INDEX idx_organisation_block_initiated_by_app_user_id (initiated_by_app_user_id) WHERE initiated_by_app_user_id IS NOT NULL
);
-- @@
CREATE TABLE IF NOT EXISTS identity_session (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  app_user_id UUID NOT NULL,
  refresh_token_hash STRING(128) NOT NULL,
  token_family_ref UUID NOT NULL,
  parent_identity_session_id UUID,
  auth_method_id UUID NOT NULL,
  mfa_satisfied BOOL NOT NULL DEFAULT false,
  acting_organisation_id UUID,
  device_session_id UUID,
  issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  absolute_expires_at TIMESTAMPTZ NOT NULL,
  last_used_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  session_revoke_reason_id UUID,
  ip_address INET NOT NULL,
  user_agent STRING(512) NOT NULL,
  CONSTRAINT pk_identity_session PRIMARY KEY (id),
  CONSTRAINT ck_identity_session_expiry_order CHECK (expires_at > issued_at AND absolute_expires_at >= expires_at),
  CONSTRAINT ck_identity_session_revoke_pair CHECK ((revoked_at IS NULL) = (session_revoke_reason_id IS NULL)),
  CONSTRAINT fk_identity_session_app_user_id FOREIGN KEY (app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_identity_session_parent_identity_session_id FOREIGN KEY (parent_identity_session_id) REFERENCES identity_session (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_identity_session_auth_method_id FOREIGN KEY (auth_method_id) REFERENCES auth_method (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_identity_session_acting_organisation_id FOREIGN KEY (acting_organisation_id) REFERENCES organisation (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_identity_session_session_revoke_reason_id FOREIGN KEY (session_revoke_reason_id) REFERENCES session_revoke_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_identity_session_refresh_token_hash (refresh_token_hash),
  INDEX idx_identity_session_app_user_id_expires_at (app_user_id, expires_at DESC) STORING (token_family_ref) WHERE revoked_at IS NULL,
  INDEX idx_identity_session_token_family_ref (token_family_ref),
  INDEX idx_identity_session_expires_at (expires_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_identity_session_parent_identity_session_id (parent_identity_session_id) WHERE parent_identity_session_id IS NOT NULL,
  INDEX idx_identity_session_acting_organisation_id (acting_organisation_id),
  INDEX idx_identity_session_device_session_id (device_session_id)
) WITH (ttl_expiration_expression = '(expires_at + INTERVAL ''7 days'')', ttl_job_cron = '@daily');
